const termDefinitions = {
    'Ação': { definition: 'Título que representa uma parte proporcional do capital social de uma empresa.', example: 'Se você compra uma ação da Apple, você é dono de uma pequena parte da companhia.' },
    'Ativo': { definition: 'Bem ou direito que uma pessoa ou empresa possui e que pode gerar benefícios futuros.', example: 'Uma casa, um carro ou dinheiro no banco são exemplos de ativos.' },
    'Poupança': { definition: 'Parte da renda que não é gasta e é reservada para necessidades futuras.', example: 'Guardar 10% do seu salário todo mês é uma boa prática de poupança.' },
    'Amortização': { definition: 'Processo de pagamento gradual de uma dívida ou a perda de valor de um ativo com o tempo.', example: 'A amortização da sua hipoteca dura 30 anos.' },
    'Tarifa': { definition: 'Imposto aplicado aos bens que são importados ou exportados.', example: 'O governo impôs uma tarifa de 20% ao aço estrangeiro.' },
    'Auditoria': { definition: 'Revisão sistemática das contas e demonstrações financeiras de uma empresa.', example: 'Uma auditoria externa confirmou que as contas da empresa estavam corretas.' },
    'Alavancagem': { definition: 'Uso de dívida para financiar uma operação com a esperança de que a rentabilidade seja superior ao custo do juros.', example: 'A alavancagem pode multiplicar os ganhos, mas também as perdas.' },
    'Alocação de Ativos': { definition: 'Estratégia de investimento que equilibra o risco e a recompensa mediante a repartição dos ativos de uma carteira.', example: 'Uma alocação de ativos comum é 60% em ações e 40% em títulos.' },
    'Balanço': { definition: 'Demonstração financeira que mostra os ativos, passivos e patrimônio de uma empresa em um momento específico.', example: 'O balanço mostra que a empresa tem mais ativos do que passivos.' },
    'Banco': { definition: 'Instituição financeira que aceita depósitos e concede empréstimos.', example: 'Você pode abrir uma conta poupança em qualquer banco comercial.' },
    'Banco Central': { definition: 'Instituição governamental responsável pela política monetária de um país.', example: 'O Banco Central controla a taxa de juros básica da economia.' },
    'Benefício': { definition: 'Ganho ou lucro obtido de uma atividade ou investimento.', example: 'O benefício fiscal reduziu o imposto de renda da empresa.' },
    'Bolsa de Valores': { definition: 'Mercado organizado onde são negociadas ações de empresas públicas.', example: 'As ações da Petrobras são negociadas na Bolsa de Valores de São Paulo.' },
    'Título': { definition: 'Instrumento financeiro que representa uma dívida ou propriedade.', example: 'Títulos do governo pagam juros fixos aos investidores.' },
    'Bolha': { definition: 'Quando os preços de ativos sobem muito acima do seu valor real, frequentemente seguido de uma queda.', example: 'A bolha imobiliária de 2008 causou uma crise financeira global.' },
    'Falência': { definition: 'Processo legal para indivíduos ou empresas que não podem pagar suas dívidas.', example: 'Depois de acumular R$ 100.000 em dívidas, declarar falência ajudou a reestruturar os pagamentos.' },
    'Balança Comercial': { definition: 'Diferença entre exportações e importações de um país.', example: 'O Brasil teve superávit na balança comercial em 2023.' },
    'Capital': { definition: 'Recursos financeiros disponíveis para investimento ou produção.', example: 'A empresa precisou de capital de R$ 1 milhão para expandir.' },
    'Capitalização de Mercado': { definition: 'Valor total de mercado de todas as ações de uma empresa.', example: 'A capitalização de mercado da Apple ultrapassou US$ 3 trilhões.' },
    'Ciclo Econômico': { definition: 'Flutuações periódicas na atividade econômica entre períodos de expansão e recessão.', example: 'O ciclo econômico dura em média de 5 a 10 anos.' },
    'Cobertura': { definition: 'Estratégia para reduzir o risco de perdas em investimentos.', example: 'Usar opções como cobertura protege contra quedas no preço das ações.' },
    'Comissão': { definition: 'Taxa cobrada por um serviço ou transação.', example: 'O corretor cobra uma comissão de 2% sobre a venda da casa.' },
    'Consumo': { definition: 'Uso de bens e serviços para satisfazer necessidades.', example: 'O consumo das famílias representa 60% do PIB.' },
    'Custo de Oportunidade': { definition: 'Valor da melhor alternativa que se renuncia ao tomar uma decisão.', example: 'O custo de oportunidade de estudar em tempo integral é o salário que você deixa de ganhar.' },
    'Crédito': { definition: 'Capacidade de obter bens ou dinheiro em troca da promessa de pagamento futuro.', example: 'Seu bom histórico de crédito permite taxas de juros mais baixas.' },
    'Criptomoeda': { definition: 'Moeda digital que usa criptografia para segurança.', example: 'Bitcoin é a criptomoeda mais conhecida do mundo.' },
    'Déficit': { definition: 'Quando as despesas excedem as receitas.', example: 'O governo registrou um déficit de R$ 100 bilhões este ano.' },
    'Deflação': { definition: 'Queda geral e sustentada dos preços na economia.', example: 'A deflação pode ser prejudicial porque reduz lucros das empresas.' },
    'Demanda': { definition: 'Quantidade de um bem ou serviço que os consumidores desejam comprar.', example: 'A demanda por máscaras aumentou durante a pandemia.' },
    'Depósito': { definition: 'Dinheiro colocado em uma conta bancária.', example: 'Você fez um depósito de R$ 5.000 na sua conta poupança.' },
    'Depreciação': { definition: 'Perda de valor de um ativo ao longo do tempo.', example: 'Carros sofrem depreciação de cerca de 20% no primeiro ano.' },
    'Derivativo': { definition: 'Instrumento financeiro cujo valor deriva de um ativo subjacente.', example: 'Opções e futuros são tipos de derivativos.' },
    'Dívida': { definition: 'Obrigação de pagar dinheiro a outra pessoa ou instituição.', example: 'A dívida pública do Brasil ultrapassa 70% do PIB.' },
    'Diversificação': { definition: 'Estratégia de investir em diferentes ativos para reduzir risco.', example: 'Diversificação significa não colocar todos os ovos na mesma cesta.' },
    'Dividendo': { definition: 'Parte do lucro de uma empresa distribuída aos acionistas.', example: 'A empresa pagou dividendos de R$ 2 por ação.' },
    'Divisa': { definition: 'Moeda estrangeira usada em transações internacionais.', example: 'O dólar é a principal divisa nas reservas internacionais.' },
    'Economia de Mercado': { definition: 'Sistema econômico baseado na oferta e demanda com mínima intervenção governamental.', example: 'Nos Estados Unidos, a economia de mercado determina a maioria dos preços.' },
    'Especulação': { definition: 'Compra de ativos com o objetivo de vendê-los por um preço maior.', example: 'A especulação imobiliária fez os preços das casas subirem rapidamente.' },
    'Estagflação': { definition: 'Situação econômica com inflação alta e crescimento baixo simultaneamente.', example: 'A estagflação dos anos 1970 foi um desafio para os economistas.' },
    'Euro': { definition: 'Moeda oficial da União Europeia.', example: 'O euro é usado por 20 países da Europa.' },
    'Excedente': { definition: 'Quantidade que sobra quando a oferta excede a demanda.', example: 'O excedente de produção foi exportado para outros países.' },
    'Exportação': { definition: 'Venda de bens ou serviços para outros países.', example: 'O Brasil é um grande exportador de soja e minério de ferro.' },
    'Fiança': { definition: 'Garantia dada por uma pessoa para assegurar o cumprimento de uma obrigação.', example: 'Seu pai serviu como fiança para o empréstimo estudantil.' },
    'Fideicomisso': { definition: 'Acordo legal onde uma parte detém propriedade em benefício de outra.', example: 'O fideicomisso protege os bens da família.' },
    'Finanças': { definition: 'Gestão de dinheiro e investimentos.', example: 'Estudar finanças pessoais ajuda a tomar melhores decisões.' },
    'Fiscalidade': { definition: 'Sistema de impostos e tributos de um país.', example: 'A fiscalidade brasileira é uma das mais complexas do mundo.' },
    'Fundo de Hedge': { definition: 'Fundo de investimento que usa estratégias complexas para gerar retornos.', example: 'Fundos de hedge cobram taxas altas mas buscam retornos superiores.' },
    'Fundo de Investimento': { definition: 'Pool de dinheiro de vários investidores gerido profissionalmente.', example: 'Você investiu R$ 10.000 em um fundo de ações.' },
    'Fundo Indexado': { definition: 'Fundo que replica o desempenho de um índice de mercado.', example: 'Um fundo indexado ao Ibovespa acompanha o desempenho da bolsa brasileira.' },
    'Fusão': { definition: 'Combinação de duas empresas em uma única entidade.', example: 'A fusão criou a maior empresa de telecomunicações do país.' },

    // G
    'Gasto Público': { definition: 'Dinheiro que o estado emprega em bens e serviços públicos.', example: 'O gasto público em educação aumentou este ano.' },
    'Garantia': { definition: 'Segurança que se oferece para assegurar o pagamento de uma dívida.', example: 'A casa serviu de garantia para o empréstimo hipotecário.' },
    'Ganho de Capital': { definition: 'Benefício obtido pela venda de um ativo a um preço superior ao de compra.', example: 'Terá que pagar impostos sobre o ganho de capital de suas ações.' },
    'Globalização': { definition: 'Processo de interconexão e interdependência das economias mundiais.', example: 'A globalização permite comprar produtos de qualquer parte do mundo.' },
    'Gasto Corrente': { definition: 'Dinheiro que o estado ou uma empresa dedica ao funcionamento diário (salários, suprimentos).', example: 'O gasto corrente do município aumentou devido à alta da luz.' },
    'Gasto de Capital': { definition: 'Investimento em ativos fixos que aumentam o patrimônio ou a capacidade produtiva.', example: 'A compra de novas vans é um gasto de capital para a empresa de entregas.' },
    'Gastos de Exploração': { definition: 'Custos necessários para manter em funcionamento um negócio ou atividade econômica.', example: 'Reduzir os gastos de exploração é chave para melhorar a margem líquida.' },
    'G-20': { definition: 'Fórum internacional dos governantes e presidentes de bancos centrais das 20 economias mais importantes do mundo.', example: 'O G-20 se reuniu para coordenar políticas contra a crise financeira global.' },
    'Ganância': { definition: 'Benefício econômico obtido de uma atividade ou investimento.', example: 'O ganho obtido na venda das ações foi maior do que o esperado.' },
    'Gerência': { definition: 'Cargo ou departamento encarregado da gestão e direção de uma empresa.', example: 'A gerência decidiu mudar o sistema de incentivos para os vendedores.' },
    'Gestor': { definition: 'Pessoa que administra bens ou interesses alheios, ou tramita assuntos administrativos.', example: 'Meu gestor se encarrega de apresentar todos os modelos de impostos trimestrais.' },
    'Governança': { definition: 'Maneira em que se dirige e controla uma organização ou estado para assegurar seu bom funcionamento.', example: 'A boa governança corporativa é essencial para atrair investidores internacionais.' },
    'Gravame': { definition: 'Carga tributária ou obrigação que pesa sobre um bem ou pessoa.', example: 'O gravame sobre o tabaco busca reduzir seu consumo por saúde pública.' },
    'Grupo Econômico': { definition: 'Conjunto de empresas que, embora sejam juridicamente independentes, atuam sob uma mesma direção.', example: 'O grupo econômico decidiu centralizar as compras para economizar custos.' },
    'Garantia Hipotecária': { definition: 'Direito que se outorga sobre um imóvel para assegurar o pagamento de um crédito.', example: 'A garantia hipotecária é o que permite ao banco leiloar a casa se você não pagar.' },

    // H
    'Haver': { definition: 'Coluna direita em uma conta contábil onde se registram receitas ou aumentos de passivo.', example: 'Anote essa receita no haver da conta.' },
    'Hipoteca': { definition: 'Empréstimo a longo prazo garantido por um bem imóvel.', example: 'Acabei de assinar uma hipoteca de 25 anos para meu apartamento.' },
    'Hiperinflação': { definition: 'Inflação extremamente alta e fora de controle.', example: 'A Venezuela sofreu hiperinflação, onde os preços mudavam todos os dias.' },
    'Holding': { definition: 'Sociedade que possui a maioria das ações e o controle de outras companhias.', example: 'A Inditex é a holding que controla marcas como Zara e Massimo Dutti.' },
    'Fazenda Pública': { definition: 'Conjunto de órgãos do estado encarregados da gestão dos recursos públicos e impostos.', example: 'A Fazenda Pública investiga a origem dos fundos não declarados.' },
    'Fato Gerador': { definition: 'Circunstância cuja realização gera a obrigação de pagar um imposto.', example: 'A compra de um carro é o fato gerador do imposto de transmissão.' },
    'Herança': { definition: 'Conjunto de bens e dívidas que se transmitem aos herdeiros após o falecimento de uma pessoa.', example: 'A gestão da herança se complicou pela falta de um testamento claro.' },
    'Hipoteca Reversa': { definition: 'Empréstimo para maiores de 65 anos garantido por sua moradia, que não se devolve até o falecimento.', example: 'A hipoteca reversa permite aos aposentados complementar sua pensão.' },
    'Honorários': { definition: 'Retribuição que recebe um profissional liberal (advogado, médico) por seus serviços.', example: 'Os honorários do arquiteto foram fixados como uma porcentagem do orçamento.' },

    // I
    'Importação': { definition: 'Compra de bens ou serviços provenientes de outro país.', example: 'A importação de petróleo é vital para países sem reservas energéticas.' },
    'Imposto': { definition: 'Tributo que os cidadãos pagam ao estado para financiar o gasto público.', example: 'O IVA é um imposto sobre o consumo.' },
    'Índice de Preços': { definition: 'Medida estatística da evolução dos preços (como o IPCA).', example: 'O índice de preços subiu 3% este mês.' },
    'Inflação': { definition: 'Aumento generalizado e sustentado dos preços de bens e serviços.', example: 'A inflação faz com que seu dinheiro compre menos coisas com o tempo.' },
    'Receita': { definition: 'Entrada de dinheiro que recebe uma pessoa ou empresa.', example: 'Suas receitas provêm principalmente de seu salário e aluguéis.' },
    'Insolvência': { definition: 'Incapacidade para pagar as dívidas quando vencem.', example: 'A empresa se declarou em insolvência ao não poder pagar seus fornecedores.' },
    'Juros': { definition: 'Preço que se paga pelo uso do dinheiro alheio, ou rendimento de um investimento.', example: 'O banco me cobra 5% de juros pelo empréstimo.' },
    'Investimento': { definition: 'Uso de capital com o objetivo de obter um benefício futuro.', example: 'Comprar ações é um investimento a longo prazo.' },
    'I+D+i': { definition: 'Investigação, Desenvolvimento e Inovação tecnológica.', example: 'As empresas que mais investem em I+D+i costumam ser as mais competitivas.' },
    'IBAN': { definition: 'Código internacional para identificar contas bancárias de forma única.', example: 'Preciso do seu código IBAN para fazer a transferência do pagamento.' },
    'Imposto de Renda': { definition: 'Imposto progressivo sobre os rendimentos das pessoas físicas.', example: 'A declaração do Imposto de Renda deve ser apresentada entre março e abril de cada ano.' },
    'Inadimplência': { definition: 'Falta de realização de uma obrigação acordada em um contrato ou lei.', example: 'A inadimplência das condições do empréstimo pode levar à penhora.' },
    'Indenização': { definition: 'Compensação econômica por um dano, prejuízo ou demissão trabalhista.', example: 'Recebeu uma indenização de vinte dias por ano após sua demissão por causas objetivas.' },
    'Indexação': { definition: 'Ajuste de um valor ou preço em função da variação de um índice (como o IPCA).', example: 'A indexação das aposentadorias assegura que não percam poder aquisitivo.' },
    'Indicador Econômico': { definition: 'Dado estatístico que permite analisar a situação da economia de um país.', example: 'A taxa de desemprego é o indicador econômico que mais preocupa a sociedade.' },
    'Inflação Subjacente': { definition: 'Índice de inflação que exclui os preços de energia e alimentos não elaborados por serem voláteis.', example: 'O Banco Central observa a inflação subjacente para ver a tendência de preços a longo prazo.' },
    'Infraestrutura': { definition: 'Conjunto de elementos ou serviços necessários para o funcionamento de uma economia (estradas, redes elétricas).', example: 'A melhoria da infraestrutura ferroviária impulsionou o comércio regional.' },
    'Inovação': { definition: 'Aplicação de novas ideias, processos ou produtos que agregam valor.', example: 'A inovação constante é necessária para sobreviver em mercados competitivos.' },
    'Juros Compostos': { definition: 'Juros que se calculam sobre o capital inicial e também sobre os juros acumulados de períodos anteriores.', example: 'Os juros compostos permitem que as economias cresçam de forma exponencial com o tempo.' },
    'Intermediação': { definition: 'Atividade de colocar em contato ofertantes e demandantes de fundos nos mercados.', example: 'Os bancos ganham dinheiro mediante a intermediação financeira.' },
    'Investidor': { definition: 'Pessoa ou entidade que dedica seu capital a comprar ativos para obter benefício.', example: 'O investidor analisou os riscos antes de comprar ações da startup.' },
    'IPC': { definition: 'Índice de Preços ao Consumidor; indicador que mede o custo de vida.', example: 'O IPC subiu 4% este ano devido ao preço da energia.' },

    // J
    'Aposentadoria': { definition: 'Cessação da atividade laboral por idade ou incapacidade, e a pensão que se recebe.', example: 'Está economizando para ter uma aposentadoria confortável.' },
    'Assembleia Geral': { definition: 'Reunião dos acionistas de uma empresa para tomar decisões importantes.', example: 'A Assembleia Geral aprovou as contas anuais.' },
    'Jornada Laboral': { definition: 'Tempo que cada trabalhador dedica diariamente ao seu trabalho.', example: 'A jornada laboral padrão no Brasil é de 44 horas semanais.' },
    'Justo Preço': { definition: 'Indenização justa que se paga pela desapropriação de um bem por utilidade pública.', example: 'O proprietário recorreu do justo preço ao considerá-lo inferior ao valor de mercado.' },
    'Jurisdição': { definition: 'Poder de um juiz ou autoridade para julgar e fazer executar o julgado em um território ou matéria.', example: 'Este tribunal não tem jurisdição sobre empresas estrangeiras sem sede no Brasil.' },

    // K
    'Know-how': { definition: 'Conjunto de conhecimentos técnicos e habilidades práticas de uma empresa.', example: 'O know-how de seus engenheiros é a vantagem competitiva da empresa.' },
    'Kanban': { definition: 'Sistema visual de gestão de projetos que permite ver o estado do fluxo de trabalho.', example: 'Usamos um quadro Kanban para organizar as tarefas da equipe de desenvolvimento.' },
    'Keynesianismo': { definition: 'Teoria econômica que propõe a intervenção do estado para estimular a demanda e o emprego.', example: 'O keynesianismo foi a base das políticas econômicas após a Segunda Guerra Mundial.' },

    // L
    'Longo Prazo': { definition: 'Período de tempo estendido, geralmente superior a um ano.', example: 'Investir em bolsa costuma ser mais rentável a longo prazo.' },
    'Leasing': { definition: 'Contrato de aluguel com opção de compra ao final do período.', example: 'A empresa adquiriu a maquinaria mediante um leasing.' },
    'Liquidez': { definition: 'Facilidade com a qual um ativo pode ser convertido em dinheiro efetivo.', example: 'O dinheiro em conta corrente tem alta liquidez.' },
    'Lucro': { definition: 'Ganho ou benefício que se obtém de uma coisa.', example: 'É uma organização sem fins lucrativos.' },
    'Letra de Câmbio': { definition: 'Documento mercantil pelo qual uma pessoa ordena a outra o pagamento de uma quantia de dinheiro em uma data.', example: 'O fornecedor exigiu uma letra de câmbio aceita como garantia de pagamento.' },
    'Lei da Oferta e Demanda': { definition: 'Princípio econômico que explica a relação entre a quantidade de um bem e seu preço no mercado.', example: 'A lei da oferta e demanda determinou a alta do preço do azeite.' },
    'Liberalismo': { definition: 'Doutrina econômica que defende a mínima intervenção do estado e a máxima liberdade individual.', example: 'O liberalismo econômico advoga pela redução de tarifas e regulações.' },
    'Livre Comércio': { definition: 'Sistema comercial onde não existem tarifas nem barreiras entre os países que intercambiam bens.', example: 'O tratado de livre comércio facilitou as exportações para o mercado americano.' },
    'Licitação': { definition: 'Processo de concurso público para adjudicar a realização de uma obra ou serviço.', example: 'A empresa construtora apresentou sua oferta para a licitação da nova ponte.' },
    'Liquidação': { definition: 'Processo de fechamento de uma empresa, venda de seus ativos e pagamento de dívidas.', example: 'A liquidação do imposto de renda deve ser feita antes de abril.' },
    'Logística': { definition: 'Conjunto de meios e métodos necessários para levar a cabo a organização de uma empresa, especialmente de transporte e distribuição.', example: 'A logística da Amazon é invejada por sua rapidez e eficiência.' },
    'Lucro Cessante': { definition: 'Perda de um ganho legítimo que se ia obter se não tivesse ocorrido um dano ou descumprimento.', example: 'O seguro cobriu tanto o dano direto como o lucro cessante após a inundação do local.' },

    // M
    'Macroeconomia': { definition: 'Estudo da economia em seu conjunto (país, região, mundo).', example: 'A macroeconomia analisa o desemprego, a inflação e o crescimento.' },
    'Margem': { definition: 'Diferença entre o preço de venda e o custo de produção.', example: 'Têm uma margem de benefício de 20% em cada produto.' },
    'Mercado': { definition: 'Lugar ou mecanismo onde se intercambiam bens e serviços.', example: 'O mercado imobiliário está muito ativo este ano.' },
    'Mercado em Alta': { definition: 'Período em que os preços dos ativos sobem ou se espera que subam.', example: 'Em um mercado em alta, os investidores costumam mostrar-se otimistas.' },
    'Mercado em Baixa': { definition: 'Período em que os preços dos ativos caem, geralmente 20% ou mais desde os máximos.', example: 'Durante um mercado em baixa, muitos investidores preferem manter dinheiro.' },
    'Microeconomia': { definition: 'Estudo do comportamento econômico de agentes individuais (empresas, lares).', example: 'A microeconomia analisa como você decide o que comprar.' },
    'Moeda': { definition: 'Dinheiro utilizado em um país específico.', example: 'O real é a moeda do Brasil.' },
    'Monopólio': { definition: 'Situação de mercado onde há um só vendedor para um produto.', example: 'A empresa elétrica tem um monopólio na região.' },
    'Massa Monetária': { definition: 'Quantidade total de dinheiro líquido (efetivo e depósitos) que circula em uma economia.', example: 'O Banco Central controla a massa monetária para manter a estabilidade de preços.' },
    'Matéria-Prima': { definition: 'Bem básico que se extrai da natureza para ser transformado em produtos elaborados.', example: 'O ferro é a matéria-prima fundamental para a indústria do aço.' },
    'Atacadista': { definition: 'Comerciante que vende produtos em grandes quantidades a outros comerciantes ou empresas, não ao consumidor final.', example: 'Compramos os suprimentos de escritório de um atacadista para economizar custos.' },
    'Mercado de Capitais': { definition: 'Mercado financeiro onde se negociam ativos a longo prazo (ações e títulos).', example: 'As empresas recorrem ao mercado de capitais para se financiar.' },
    'Mercado de Divisas': { definition: 'Forex; mercado global onde se intercambiam as moedas dos diferentes países.', example: 'O mercado de divisas é o mais líquido e ativo do mundo.' },
    'Mercado Emergente': { definition: 'Economia com potencial de crescimento rápido que está em processo de industrialização.', example: 'Brasil e Índia são considerados mercados emergentes muito atrativos para investir.' },
    'Mercado Financeiro': { definition: 'Lugar ou mecanismo onde se intercambiam ativos financeiros e se fixam seus preços.', example: 'A estabilidade do mercado financeiro é chave para a confiança econômica.' },
    'Mercado Imobiliário': { definition: 'Setor dedicado à compra, venda e aluguel de bens imóveis.', example: 'O mercado imobiliário nas grandes cidades continua mostrando preços elevados.' },
    'Marketing': { definition: 'Conjunto de técnicas para melhorar a comercialização de um produto.', example: 'O marketing digital é essencial para alcançar o público jovem.' },
    'Microcrédito': { definition: 'Empréstimo de pequena quantia concedido a pessoas com poucos recursos para iniciar um negócio.', example: 'Os microcréditos têm ajudado muitas mulheres a empreender em países em desenvolvimento.' },
    'Modelo Econômico': { definition: 'Representação simplificada da realidade econômica para entender seu funcionamento.', example: 'O modelo econômico prevê que uma baixa de impostos estimulará o consumo.' },
    'Monetarismo': { definition: 'Teoria econômica que enfatiza o papel do governo no controle da quantidade de dinheiro em circulação.', example: 'O monetarismo sustenta que a inflação é sempre um fenômeno monetário.' },
    'Monopólio Natural': { definition: 'Situação onde uma só empresa pode produzir um bem de forma mais eficiente que várias pelos altos custos fixos.', example: 'A rede de ferrovias é um monopólio natural devido ao custo das vias.' },
    'Morosidade': { definition: 'Situação de falta de pagamento das dívidas nos prazos acordados.', example: 'A taxa de morosidade bancária subiu após o aumento do desemprego.' },
    'Multinacional': { definition: 'Empresa que opera e tem sedes em vários países do mundo.', example: 'As empresas multinacionais dominam grande parte do comércio global.' },

    // N
    'Líquido': { definition: 'Quantidade final que resta depois de realizar deduções (impostos, gastos).', example: 'Seu salário líquido é o que realmente chega à sua conta bancária.' },
    'Nicho de Mercado': { definition: 'Segmento específico do mercado com necessidades particulares.', example: 'Vender comida vegana para animais de estimação é um nicho de mercado.' },
    'Folha de Pagamento': { definition: 'Documento que detalha o salário e deduções de um trabalhador.', example: 'Revise sua folha de pagamento para ver quanto pagou de impostos.' },
    'Nacionalização': { definition: 'Processo pelo qual o estado assume a propriedade e gestão de uma empresa privada.', example: 'A nacionalização da elétrica foi uma medida para controlar os preços da energia.' },
    'Neoliberalismo': { definition: 'Corrente econômica que defende a redução da intervenção do estado e o livre mercado.', example: 'O neoliberalismo tem marcado as políticas econômicas de muitos países desde os anos 80.' },
    'Nível de Preços': { definition: 'Média ponderada dos preços dos bens e serviços de uma economia.', example: 'O nível de preços se manteve estável graças à política monetária.' },
    'Nível de Vida': { definition: 'Grau de bem-estar ou riqueza de uma pessoa ou país, medido por sua capacidade de consumo.', example: 'O aumento do salário mínimo busca melhorar o nível de vida dos trabalhadores.' },
    'Nota de Crédito': { definition: 'Documento comercial que credita que uma empresa deve dinheiro a um cliente (por devolução, etc.).', example: 'Me enviaram uma nota de crédito pelo produto que devolvi defeituoso.' },
    'Nota de Débito': { definition: 'Documento comercial que notifica a um cliente um aumento de sua dívida.', example: 'O banco emitiu uma nota de débito pela comissão de descoberto.' },
    'Notário': { definition: 'Funcionário público que dá fé legal de contratos e documentos.', example: 'Fomos ao notário para assinar a escritura de compra e venda da casa.' },

    // O
    'Oligopólio': { definition: 'Mercado dominado por um pequeno número de vendedores.', example: 'O mercado de telecomunicações costuma ser um oligopólio.' },
    'Obra Pública': { definition: 'Construção financiada pelo estado para uso da comunidade (estradas, hospitais).', example: 'O investimento em obra pública ajuda a reativar a economia em tempos de crise.' },
    'Obsolescência': { definition: 'Queda em desuso de uma máquina ou produto por falta de funcionalidade comparada com os novos.', example: 'A obsolescência programada encurta a vida útil de muitos aparelhos eletrônicos.' },
    'OCDE': { definition: 'Organização para a Cooperação e o Desenvolvimento Econômico; clube dos países mais desenvolvidos.', example: 'O Brasil busca se tornar membro da OCDE e seguir suas recomendações de política econômica.' },
    'Oferta Agregada': { definition: 'Quantidade total de bens e serviços que as empresas de um país estão dispostas a vender.', example: 'A oferta agregada se vê afetada pelo custo da energia e do trabalho.' },
    'Oferta de Dinheiro': { definition: 'Quantidade total de dinheiro de curso legal em mãos do público e depósitos bancários.', example: 'Um aumento excessivo da oferta de dinheiro pode provocar inflação.' },
    'OIT': { definition: 'Organização Internacional do Trabalho; organismo da ONU que vela pelos direitos trabalhistas.', example: 'A OIT estabelece as normas mínimas de segurança no trabalho a nível mundial.' },
    'OMC': { definition: 'Organização Mundial do Comércio; organismo que regula o comércio entre países.', example: 'A OMC media nos conflitos comerciais para evitar guerras de tarifas.' },
    'OPEP': { definition: 'Organização de Países Exportadores de Petróleo; cartel que coordena a produção de petróleo bruto.', example: 'As decisões da OPEP influenciam diretamente no preço da gasolina.' },
    'Oportunidade': { definition: 'Momento favorável para realizar um investimento ou negócio com alta probabilidade de sucesso.', example: 'A queda da bolsa foi vista como uma oportunidade de compra pelos investidores.' },
    'Ordem de Compra': { definition: 'Documento que um comprador envia a um vendedor detalhando o pedido solicitado.', example: 'Emitimos a ordem de compra para receber o material na próxima segunda-feira.' },
    'Ouro': { definition: 'Metal precioso utilizado historicamente como reserva de valor e base monetária.', example: 'O ouro costuma subir de preço quando há muita incerteza nos mercados.' },

    // P
    'Passivo': { definition: 'Conjunto de dívidas e obrigações de uma empresa ou pessoa.', example: 'O passivo da empresa inclui empréstimos bancários e contas a pagar.' },
    'Patrimônio': { definition: 'Conjunto de bens, direitos e obrigações de uma pessoa ou empresa.', example: 'Seu patrimônio líquido aumentou graças à alta de seus investimentos.' },
    'Paraíso Fiscal': { definition: 'Território que oferece impostos muito baixos ou nulos a investidores estrangeiros.', example: 'As autoridades lutam contra a evasão de capitais para paraísos fiscais.' },
    'PIB': { definition: 'Produto Interno Bruto - valor total da produção de um país.', example: 'O PIB do país cresceu 2% no último trimestre.' },
    'Mais-valia': { definition: 'Aumento do valor de um bem por causas externas.', example: 'O terreno ganhou mais-valia após a construção do metrô perto.' },
    'População Ativa': { definition: 'Pessoas em idade de trabalhar que têm emprego ou o buscam ativamente.', example: 'A população ativa diminuiu devido ao envelhecimento.' },
    'Orçamento': { definition: 'Plano financeiro que estima receitas e gastos para um período.', example: 'Fazer um orçamento mensal te ajuda a controlar seus gastos.' },
    'Prêmio de Risco': { definition: 'Sobrepreço que paga um emissor de dívida com mais risco frente a um seguro.', example: 'O prêmio de risco do país subiu pela instabilidade política.' },
    'Empréstimo': { definition: 'Dinheiro que se recebe com a obrigação de devolvê-lo com juros.', example: 'Pediu um empréstimo ao banco para comprar um carro.' },
    'Nota Promissória': { definition: 'Documento no qual uma pessoa se obriga a pagar a outra uma quantia em uma data determinada.', example: 'O cliente nos entregou uma nota promissória de sessenta dias pela compra do mobiliário.' },
    'Pânico Financeiro': { definition: 'Situação de alarme coletivo onde os investidores vendem massivamente seus ativos ou retiram depósitos.', example: 'O pânico financeiro de 1929 levou ao colapso das bolsas mundiais.' },
    'Patente': { definition: 'Direito exclusivo concedido pelo estado para explorar um invento por um tempo determinado.', example: 'A farmacêutica registrou a patente do novo fármaco para proteger seu investimento.' },
    'Padrão Ouro': { definition: 'Sistema monetário que fixa o valor da unidade monetária em termos de uma quantidade determinada de ouro.', example: 'O abandono do padrão ouro permitiu aos países ter políticas monetárias mais flexíveis.' },
    'PME': { definition: 'Pequena e Média Empresa; motor principal do emprego em muitos países.', example: 'As PMEs representam mais de 90% do tecido empresarial no Brasil.' },
    'PIB per capita': { definition: 'Relação entre o Produto Interno Bruto e o número de habitantes de um país.', example: 'O PIB per capita é um indicador mais preciso do bem-estar que o PIB total.' },
    'Plano de Pensões': { definition: 'Instrumento de poupança a longo prazo orientado a complementar a aposentadoria pública.', example: 'Faço aportes mensais ao meu plano de pensões para deduzir impostos.' },
    'Pobreza': { definition: 'Situação em que não é possível satisfazer as necessidades físicas e psíquicas básicas por falta de recursos.', example: 'A luta contra a pobreza extrema é uma prioridade dos organismos internacionais.' },
    'Poder de Compra': { definition: 'Capacidade econômica de uma pessoa para comprar bens e serviços.', example: 'Se os preços sobem mais que os salários, o poder de compra das pessoas diminui.' },
    'Apólice': { definition: 'Documento que contém as condições de um contrato de seguro.', example: 'Revisei minha apólice de casa para ver se cobria os danos elétricos.' },
    'Política Econômica': { definition: 'Conjunto de medidas e estratégias que os governos utilizam para influir na economia.', example: 'A política econômica do país busca reduzir o déficit exterior.' },
    'Política Fiscal': { definition: 'Uso do gasto público e dos impostos para influir na demanda agregada.', example: 'Uma política fiscal expansiva costuma incluir um aumento dos investimentos públicos.' },
    'Política Monetária': { definition: 'Ações dos bancos centrais para gerir a quantidade de dinheiro e as taxas de juros.', example: 'A política monetária restritiva busca frear a inflação subindo as taxas.' },
    'Portfólio': { definition: 'Carteira de investimento; conjunto de ativos financeiros que possui uma pessoa ou entidade.', example: 'Diversifiquei meu portfólio incluindo ações, títulos e um pouco de ouro.' },
    'Privatização': { definition: 'Venda de empresas ou serviços públicos ao setor privado.', example: 'A privatização da companhia aérea estatal foi um processo muito polêmico.' },
    'Produção': { definition: 'Atividade econômica que consiste em criar bens e serviços mediante a transformação de recursos.', example: 'A produção industrial cresceu três por cento no trimestre passado.' },
    'Produtividade': { definition: 'Relação entre a quantidade de produtos obtidos e os recursos utilizados para isso.', example: 'A automatização da fábrica melhorou enormemente a produtividade.' },
    'Propriedade Intelectual': { definition: 'Direitos legais sobre as criações da mente, como obras artísticas, marcas e patentes.', example: 'A lei de propriedade intelectual protege os autores frente ao plágio.' },
    'Protecionismo': { definition: 'Política econômica que busca proteger a indústria nacional mediante tarifas e barreiras à importação.', example: 'O protecionismo excessivo pode provocar represálias comerciais de outros países.' },
    'Fornecedor': { definition: 'Empresa ou pessoa que fornece os bens ou serviços necessários para a atividade de outra.', example: 'Mudamos de fornecedor de energia para reduzir os custos de fabricação.' },
    'Ponto de Equilíbrio': { definition: 'Nível de vendas em que as receitas igualam os custos totais (não há nem benefício nem perda).', example: 'Precisamos vender mil unidades por mês para alcançar o ponto de equilíbrio.' },

    // Q
    'Falência': { definition: 'Situação jurídica onde uma pessoa ou empresa não pode pagar suas dívidas.', example: 'A empresa se declarou em falência após anos de perdas.' },
    'Redução': { definition: 'Acordo para reduzir o montante de uma dívida.', example: 'Os credores aceitaram uma redução de 30% da dívida.' },
    'Quórum': { definition: 'Número mínimo de membros presentes necessário para que uma assembleia ou junta possa tomar decisões válidas.', example: 'A junta não pôde celebrar-se por falta de quórum entre os acionistas.' },
    'Quintil': { definition: 'Estatístico que divide uma população em cinco partes iguais (20% cada uma) segundo uma variável como a renda.', example: 'As pessoas do quintil mais pobre recebem 60% das ajudas sociais.' },

    // R
    'Recessão': { definition: 'Período de diminuição da atividade econômica.', example: 'Durante a recessão, muitas empresas deixaram de contratar.' },
    'Renda': { definition: 'Receita regular que produz um bem ou atividade.', example: 'Vive da renda de seus apartamentos alugados.' },
    'Rentabilidade': { definition: 'Capacidade de um investimento para gerar benefícios.', example: 'Busco um investimento com alta rentabilidade embora tenha mais risco.' },
    'Índice Preço-Lucro (P/L)': { definition: 'Relação entre o preço de uma ação e seu benefício líquido por ação.', example: 'Um P/L baixo pode indicar que uma ação está barata.' },
    'Rendimento de Dividendos': { definition: 'Porcentagem que representa o dividendo anual sobre o preço da ação.', example: 'Essa empresa tem um alto rendimento de dividendos de 5%.' },
    'Reservas': { definition: 'Fundos guardados para contingências futuras.', example: 'O banco central aumentou suas reservas de ouro.' },
    'Risco': { definition: 'Probabilidade de que um investimento perca valor.', example: 'Todo investimento envolve certo risco.' },
    'Riqueza': { definition: 'Abundância de bens e recursos.', example: 'A riqueza nacional se mede não só pelo PIB mas pelo bem-estar.' },
    'Índice de Liquidez': { definition: 'Indicador que mede a capacidade de uma empresa para pagar suas dívidas a curto prazo com seus ativos mais líquidos.', example: 'Um índice de liquidez inferior a um pode indicar problemas de tesouraria iminentes.' },
    'Índice de Solvência': { definition: 'Indicador que mede a capacidade de uma empresa para fazer frente a todas suas dívidas a longo prazo com seus ativos totais.', example: 'O banco exige um índice de solvência sólido para conceder o empréstimo hipotecário.' },
    'Arrecadação': { definition: 'Ação de cobrar ou recolher dinheiro, especialmente de impostos por parte do estado.', example: 'A arrecadação por IVA aumentou significativamente este ano devido ao consumo natalino.' },
    'Recibo': { definition: 'Documento assinado por quem recebe dinheiro ou bens para creditar a entrega.', example: 'Peça sempre o recibo de compra para poder realizar devoluções no futuro.' },
    'Reembolso': { definition: 'Devolução de uma quantidade de dinheiro a quem a pagou previamente.', example: 'Solicitei o reembolso da passagem de avião após o cancelamento do voo por mau tempo.' },
    'Refinanciamento': { definition: 'Substituição de uma dívida existente por uma nova com condições diferentes (prazo, juros).', example: 'O refinanciamento da dívida permitiu à empresa evitar a falência imediata.' },
    'Regulação': { definition: 'Conjunto de normas ditadas pelo estado para controlar o funcionamento de um mercado ou atividade.', example: 'A nova regulação bancária exige às entidades ter mais capital de reserva.' },
    'Remessa': { definition: 'Envio de dinheiro que realizam os migrantes a suas famílias em seu país de origem.', example: 'As remessas são uma fonte vital de divisas para muitos países em desenvolvimento.' },
    'Rendimento': { definition: 'Benefício ou utilidade que produz um investimento ou atividade econômica.', example: 'Este fundo de investimento deu um rendimento anual de oito por cento.' },
    'Resgate': { definition: 'Ação de salvar a uma empresa ou país da falência mediante assistência financeira pública ou privada.', example: 'O resgate bancário de 2012 custou bilhões de euros aos contribuintes.' },
    'Retenção': { definition: 'Quantidade de dinheiro que se detrai de um pagamento (salário, juros) para ingressá-la na fazenda como pagamento a conta.', example: 'A retenção do IR na minha folha é de quinze por cento.' },
    'Retorno de Investimento (ROI)': { definition: 'Métrica que mede a rentabilidade de um investimento comparando o benefício obtido com o capital investido.', example: 'O ROI da nossa campanha publicitária foi excelente: por cada real investido ganhamos cinco.' },
    'Risco Cambial': { definition: 'Possibilidade de perda devida às variações na taxa de câmbio das moedas.', example: 'As empresas que exportam aos Estados Unidos se enfrentam ao risco cambial do dólar.' },
    'Risco de Mercado': { definition: 'Risco de que o valor de um investimento diminua devido a mudanças gerais no mercado (taxas de juros, preços).', example: 'O risco de mercado é inevitável se você investe em renda variável.' },
    'Risco Sistêmico': { definition: 'Probabilidade de que a falha de uma entidade ou mercado provoque um colapso em todo o sistema financeiro.', example: 'A queda do Lehman Brothers provocou um risco sistêmico que afetou todo o mundo.' },
    'Royalty': { definition: 'Pagamento que se realiza pelo uso de uma propriedade intelectual ou exploração de recursos naturais.', example: 'O escritor recebe um royalty de dez por cento por cada livro vendido.' },

    // S
    'Saldo': { definition: 'Diferença entre o deve e o haver; quantidade disponível em uma conta.', example: 'Seu saldo bancário é positivo.' },
    'Setor Público': { definition: 'Conjunto de órgãos e empresas controladas pelo estado.', example: 'O setor público emprega milhões de trabalhadores no país.' },
    'Seguro': { definition: 'Contrato para proteger-se contra perdas financeiras.', example: 'É obrigatório ter um seguro de carro.' },
    'Sistema Financeiro': { definition: 'Conjunto de instituições, mercados e instrumentos que canalizam a poupança para o investimento.', example: 'A estabilidade do sistema financeiro é fundamental para a economia.' },
    'Solvência': { definition: 'Capacidade para fazer frente às dívidas.', example: 'O banco demonstrou sua solvência nos testes de estresse.' },
    'Superávit': { definition: 'Situação onde as receitas superam os gastos.', example: 'O país logrou um superávit comercial este ano.' },
    'Suspensão de Pagamentos': { definition: 'Situação legal de uma empresa que não pode pagar suas dívidas por falta de liquidez temporária.', example: 'A empresa solicitou a suspensão de pagamentos para tentar negociar com os bancos.' },
    'Segmentação de Mercado': { definition: 'Divisão do mercado em grupos menores de consumidores com características similares.', example: 'A segmentação de mercado nos permitiu dirigir o produto só aos jovens esportistas.' },
    'Seguro de Vida': { definition: 'Contrato pelo qual o segurador paga uma quantia aos beneficiários após o falecimento do segurado.', example: 'Contratou um seguro de vida ao pedir a hipoteca para proteger sua família.' },
    'Serviço': { definition: 'Bem intangível que consiste em realizar uma atividade para satisfazer uma necessidade ou desejo humano.', example: 'O setor de serviços é o que mais peso tem na economia brasileira.' },
    'Sindicato': { definition: 'Associação de trabalhadores para a defesa e promoção de seus interesses trabalhistas e econômicos.', example: 'O sindicato negociou com a patronal o novo convênio coletivo do setor.' },
    'Sistema Econômico': { definition: 'Forma em que uma sociedade organiza a produção e distribuição de bens e serviços.', example: 'Existem diferentes sistemas econômicos, como o capitalismo de mercado ou a economia planificada.' },
    'Sistema Monetário': { definition: 'Conjunto de normas e instituições que regulam o uso da moeda e do crédito em um país ou zona.', example: 'O real é a unidade básica do sistema monetário do Brasil.' },
    'Sociedade Anônima (S.A.)': { definition: 'Empresa cujo capital está dividido em ações e onde os sócios só respondem com o capital aportado.', example: 'A maioria das grandes empresas que cotizam em bolsa são sociedades anônimas.' },
    'Sociedade de Responsabilidade Limitada (Ltda.)': { definition: 'Empresa com capital dividido em participações, ideal para negócios pequenos e médios por sua menor exigência de capital.', example: 'Registramos nossa pequena oficina como uma sociedade de responsabilidade limitada.' },
    'Sustentabilidade': { definition: 'Capacidade de manter a atividade econômica a longo prazo sem esgotar os recursos naturais ou danificar o meio ambiente.', example: 'A sustentabilidade é agora um critério chave para receber fundos de investimento internacionais.' },
    'Spread': { definition: 'Diferencial entre o preço de compra e o de venda de um ativo, ou entre duas taxas de juros.', example: 'O spread do título brasileiro frente ao americano é um indicador do risco país.' },
    'Leilão': { definition: 'Venda pública de bens ao melhor licitante baseando-se na competição de preços.', example: 'A Receita Federal leiloou os carros apreendidos para recuperar parte da dívida.' },
    'Subsídio': { definition: 'Ajuda econômica do governo a empresas ou pessoas.', example: 'Receberam um subsídio para instalar painéis solares.' },
    'Superávit Comercial': { definition: 'Situação em que as exportações de um país superam suas importações.', example: 'O Brasil tem tido um superávit comercial constante nas últimas décadas.' },
    'Superávit Fiscal': { definition: 'Ocorre quando as receitas do estado superam seus gastos em um exercício.', example: 'O governo usará o superávit fiscal para reduzir a dívida pública acumulada.' },
    'Swap': { definition: 'Contrato financeiro pelo qual duas partes intercambiam fluxos de dinheiro ou benefícios.', example: 'Usamos um swap de taxas de juros para passar nossa dívida de variável a fixa.' },
    'SWIFT': { definition: 'Sistema global de mensagens financeiras que permite realizar transferências bancárias internacionais de forma segura.', example: 'Sem o código SWIFT do banco não é possível realizar ingressos desde o exterior.' },

    // T
    'Taxa de Juros': { definition: 'Porcentagem que se paga por um empréstimo ou se recebe por um depósito.', example: 'A taxa de juros subiu a 4%.' },
    'Taxa de Desemprego': { definition: 'Porcentagem da população ativa que não tem emprego.', example: 'A taxa de desemprego baixou a 3.5%.' },
    'Taxa de Câmbio': { definition: 'Preço de uma moeda em termos de outra.', example: 'A taxa de câmbio real-dólar favorece os exportadores.' },
    'Título': { definition: 'Documento que credita um direito ou propriedade.', example: 'Tem um título de propriedade da casa.' },
    'Tributo': { definition: 'Pagamento obrigatório ao estado (impostos, taxas).', example: 'Deve pagar seus tributos pontualmente.' },
    'Taxa de Atividade': { definition: 'Porcentagem da população em idade de trabalhar que está empregada ou busca emprego ativamente.', example: 'A taxa de atividade feminina cresceu notavelmente na última década.' },
    'Taxa de Crescimento': { definition: 'Porcentagem em que aumenta ou diminui uma variável econômica (como o PIB) em um tempo.', example: 'A taxa de crescimento da economia se estagnou devido à crise energética.' },
    'Taxa de Desconto': { definition: 'Tipo de juros utilizado para calcular o valor atual dos recebimentos ou pagamentos futuros.', example: 'Aplicamos uma taxa de desconto de dez por cento para avaliar o projeto de investimento.' },
    'Taxa de Inflação': { definition: 'Porcentagem que mede o aumento generalizado dos preços em um período.', example: 'A taxa de inflação interanual alcançou máximos históricos no mês passado.' },
    'Taxa Interna de Retorno (TIR)': { definition: 'Tipo de juros que faz com que o valor atual líquido de um investimento seja igual a zero.', example: 'Só aprovamos projetos cuja TIR seja superior ao custo de financiamento.' },
    'Avaliação': { definition: 'Estimativa do valor econômico de um bem realizada por um especialista.', example: 'A avaliação da moradia é um passo prévio obrigatório para a concessão da hipoteca.' },
    'Tecnologia': { definition: 'Conjunto de conhecimentos e ferramentas aplicados à produção de bens e serviços.', example: 'O investimento em tecnologia é chave para melhorar a competitividade das empresas.' },
    'Teletrabalho': { definition: 'Atividade laboral que se realiza a distância utilizando meios telemáticos.', example: 'O teletrabalho permitiu uma melhor conciliação entre a vida familiar e laboral.' },
    'Tendência': { definition: 'Direção geral em que se move um mercado ou indicador ao longo do tempo.', example: 'A tendência do mercado de valores é claramente altista desde o início do ano.' },
    'Teoria dos Jogos': { definition: 'Área da economia que estuda as decisões ótimas entre agentes que interagem entre si.', example: 'A teoria dos jogos se aplica para entender as guerras de preços em um oligopólio.' },
    'Tesouraria': { definition: 'Departamento de uma empresa que gere os recebimentos, pagamentos e a liquidez diária.', example: 'A tesouraria da companhia está em níveis mínimos devido ao atraso nos pagamentos dos clientes.' },
    'Tesouro Público': { definition: 'Órgão do estado que gere a dívida pública e as finanças nacionais.', example: 'O Tesouro Público emitiu letras de três meses com um juro muito atrativo.' },
    'Transparência': { definition: 'Princípio de clareza e acesso à informação na gestão econômica e pública.', example: 'A transparência financeira é essencial para gerar confiança nos investidores.' },
    'Troca': { definition: 'Intercâmbio direto de bens ou serviços sem a mediação de dinheiro.', example: 'A troca foi a forma primitiva de comércio antes da invenção da moeda.' },

    // U
    'Umbral de Rentabilidade': { definition: 'Ponto onde as receitas igualam os custos (ponto de equilíbrio).', example: 'A empresa alcançará o umbral de rentabilidade em seu segundo ano.' },
    'Utilidade': { definition: 'Benefício ou ganho líquido; também satisfação que dá um bem.', example: 'A utilidade líquida foi maior do que a esperada.' },
    'UE (União Europeia)': { definition: 'Comunidade política de direito constituída em regime sui generis de organização internacional nascida para propiciar e acolher a integração e governança em comum dos Estados e os povos da Europa.', example: 'A UE facilita o livre comércio entre seus estados membros.' },
    'Unidade de Conta': { definition: 'Função do dinheiro que permite expressar o valor de todos os bens e serviços em uma unidade comum.', example: 'O euro atua como unidade de conta em toda a zona do euro.' },
    'Unidade Monetária': { definition: 'Tipo de moeda que utiliza um país ou território para suas transações.', example: 'O franco suíço é uma das unidades monetárias mais estáveis do mundo.' },
    'União Aduaneira': { definition: 'Área de livre comércio que além disso estabelece uma tarifa exterior comum frente a terceiros países.', example: 'A União Aduaneira da UE permite que as mercadorias circulem sem controles fronteiriços internos.' },
    'União Econômica': { definition: 'Mercado comum que além disso implica a harmonização das políticas econômicas dos estados membros.', example: 'A União Econômica e Monetária é o passo mais avançado da integração europeia.' },
    'União Monetária': { definition: 'Acordo entre dois ou mais países para compartilhar a mesma moeda.', example: 'A União Monetária permite reduzir os custos de transação no comércio internacional.' },
    'Usura': { definition: 'Cobrança de juros excessivamente altos em um empréstimo, frequentemente considerados ilegais.', example: 'O tribunal anulou o contrato do cartão de crédito por considerá-lo usura.' },

    // V
    'Volatilidade': { definition: 'Medida da variação do preço de um ativo.', example: 'As criptomoedas têm alta volatilidade.' },
    'Valor de Mercado': { definition: 'Preço que se pagaria por um ativo em um mercado aberto e competitivo.', example: 'O valor de mercado da empresa disparou após o anúncio da patente.' },
    'Valor de Reposição': { definition: 'Custo de voltar a adquirir ou fabricar um bem com as mesmas características no momento atual.', example: 'O seguro pagou o valor de reposição da maquinaria após o incêndio.' },
    'Valor Nominal': { definition: 'Valor que figura de forma explícita em um título ou documento, sem ter em conta a inflação ou o valor real.', example: 'O valor nominal da ação é de um real, embora cotize a dez.' },
    'Valor Real': { definition: 'Valor de um bem ou renda expresso em termos de poder aquisitivo, ajustado pela inflação.', example: 'O salário real baixou este ano apesar de que o nominal tenha subido ligeiramente.' },
    'Valor Residual': { definition: 'Valor que tem um ativo ao final de sua vida útil, depois de ter sido amortizado.', example: 'Estimamos um valor residual de cinco por cento para os computadores após quatro anos de uso.' },
    'Valoração': { definition: 'Processo de atribuir um valor econômico a algo baseando-se em critérios técnicos e de mercado.', example: 'A valoração da startup para a rodada de investimento superou todas as expectativas.' },
    'Vida Útil': { definition: 'Período durante o qual se espera que um ativo seja produtivo ou funcional para a empresa.', example: 'A vida útil deste caminhão de entrega é de aproximadamente oito anos.' },
    'Moradia': { definition: 'Bem imóvel destinado à habitação de pessoas; é um dos principais ativos de poupança das famílias.', example: 'O investimento em moradia costuma considerar-se seguro a longo prazo neste país.' },
    'Volume de Negócios': { definition: 'Cifra total de vendas ou receitas que gera uma empresa em um exercício fiscal.', example: 'Apesar da crise, o volume de negócios da companhia aumentou cinco por cento.' },

    // W
    'Warrant': { definition: 'Produto financeiro que dá direito a comprar ou vender um ativo a um preço fixo.', example: 'Os warrants são instrumentos complexos para investidores avançados.' },
    'Wall Street': { definition: 'Centro financeiro de Nova York onde se encontra a bolsa de valores mais importante do mundo.', example: 'Wall Street reagiu com otimismo às notícias sobre as taxas de juros.' },
    'Web 3.0': { definition: 'Evolução da internet baseada na descentralização, as tecnologias blockchain e a propriedade do usuário.', example: 'A Web 3.0 promete mudar a forma em que interagimos com as finanças digitais.' },
    'Bem-Estar': { definition: 'Estado de bem-estar; sistema que busca garantir níveis básicos de saúde, educação e renda para todos os cidadãos.', example: 'O sistema de bem-estar europeu se financia principalmente através de impostos progressivos.' },

    // Y
    'Rendimento': { definition: 'Rentabilidade de um investimento expressa em porcentagem.', example: 'O rendimento deste título é de 5%.' },
    'Jazida': { definition: 'Acumulação natural de minerais ou hidrocarbonetos que pode ser explorada economicamente.', example: 'A descoberta de uma nova jazida de lítio impulsionou a economia da região.' },

    // Z
    'Zona do Euro': { definition: 'Área geográfica formada pelos países da União Europeia que adotaram o euro como moeda.', example: 'A Zona do Euro inclui 20 países da União Europeia.' },
    'Zona Franca': { definition: 'Área geográfica com benefícios fiscais para atrair investimento.', example: 'A empresa se instalou em uma zona franca para pagar menos impostos.' },
    'Safra': { definition: 'Colheita da cana-de-açúcar ou época em que se recolhe; termo agrícola com grande impacto econômico regional.', example: 'A economia local depende inteiramente do sucesso da safra anual.' },
};
